import { createReadStream } from 'node:fs';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { Readable } from 'node:stream';

import type { StorageProvider } from './storage-provider';

/** Local-disk storage. Object keys are generated by us (never user input) and confined to the root. */
export class LocalStorageProvider implements StorageProvider {
  readonly name = 'local' as const;
  readonly bucket = 'local';
  private readonly root: string;

  constructor(root: string) {
    this.root = path.resolve(root);
  }

  private pathOf(objectKey: string): string {
    if (!/^[a-z0-9/_-]+(\.[a-z0-9]+)?$/.test(objectKey) || objectKey.includes('..')) {
      throw new Error(`Invalid object key: ${objectKey}`);
    }
    const full = path.resolve(this.root, objectKey);
    if (!full.startsWith(this.root + path.sep)) throw new Error('Object key escapes storage root');
    return full;
  }

  async put(objectKey: string, body: Buffer): Promise<void> {
    const file = this.pathOf(objectKey);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, body, { flag: 'w' });
  }

  get(objectKey: string): Promise<Readable> {
    return Promise.resolve(createReadStream(this.pathOf(objectKey)));
  }

  async delete(objectKey: string): Promise<void> {
    await rm(this.pathOf(objectKey), { force: true });
  }
}
